#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<ll> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }

    vector<vector<int>> g(n + 1);
    for (int i = 1; i < n; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    ll res = 0;
    ll cum[2] = {0, 0}; // cum[0] 偶深度, cum[1] 奇深度

    struct StackFrame {
        int u, p, d, stg;
        ll x;
    };
    vector<StackFrame> stk;
    stk.reserve(2 * n);
    stk.push_back({1, 0, 0, 0, 0});

    while (!stk.empty()) {
        auto [u, p, d, stg, x] = stk.back();
        stk.pop_back();

        if (stg == 0) {
            int pp = d & 1;
            ll need = cum[pp] ^ a[u];
            res += need;
            cum[pp] ^= need;

            stk.push_back({u, p, d, 1, need});
            for (int v : g[u]) {
                if (v != p) {
                    stk.push_back({v, u, d + 1, 0, 0});
                }
            }
        } else {
            int pp = d & 1;
            cum[pp] ^= x; // 撤销操作
        }
    }

    cout << res << '\n';
    return 0;
}
